code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0 = min(r for r, c in ones)
    r1 = max(r for r, c in ones)
    c0 = min(c for r, c in ones)
    c1 = max(c for r, c in ones)
    rect = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    H, W = len(rect), len(rect[0])
    # The three boundary markers in the panel correspond to the three isolated markers outside it.
    inside = {}
    outside = {}
    for r in range(H):
        for c in range(W):
            v = rect[r][c]
            if v != 1 and (r in (0, H - 1) or c in (0, W - 1)):
                inside[v] = (r, c)
    for r in range(h):
        for c in range(w):
            if not (r0 <= r <= r1 and c0 <= c <= c1) and grid[r][c] != 0:
                outside[grid[r][c]] = (r, c)
    colors = [v for v in inside if v in outside]
    def apply(r, c, flip, turns):
        hh, ww = H, W
        if flip:
            c = ww - 1 - c
        for _ in range(turns):
            r, c = c, hh - 1 - r
            hh, ww = ww, hh
        return r, c
    best = None
    for flip in range(2):
        for turns in range(4):
            pts = {v: apply(*inside[v], flip, turns) for v in colors}
            # Match the pairwise displacement vectors of the outside markers.
            score = sum((pts[b][0] - pts[a][0] - (outside[b][0] - outside[a][0])) ** 2 +
                        (pts[b][1] - pts[a][1] - (outside[b][1] - outside[a][1])) ** 2
                        for a in colors for b in colors)
            if best is None or score < best[0]:
                best = (score, flip, turns)
    _, flip, turns = best
    out = [[0] * W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            rr, cc = apply(r, c, flip, turns)
            out[rr][cc] = rect[r][c]
    return out
'''
